const JOB_STATUS = {
  PICKED: 'PICKED', SIBLING: 'SIBLING', COOLDOWN: 'COOLDOWN', LOW_SCORE: 'LOW_SCORE', NO_CONTACTS: 'NO_CONTACTS',
  EXPIRED: 'EXPIRED', LEGACY: 'LEGACY', UNRESOLVED: 'UNRESOLVED',
};

// ── company.js ──────────────────────────────────────────────────────────────
// Resolve any spelling of a company (LinkedIn display name, Cowork output,
// legacy sheet text) to the Companies tab's CompanyID. Never guesses: if two
// different IDs match, or nothing matches, it returns ''.

const COMPANY_NOISE = new Set([
  'technologies', 'technology', 'tech', 'group', 'india', 'private', 'pvt', 'limited', 'ltd',
  'inc', 'llc', 'llp', 'corp', 'corporation', 'co', 'company', 'holdings', 'holding', 'advertising',
  'global', 'labs', 'software', 'systems', 'services', 'solutions', 'the', 'and', 'plc', 'gmbh',
]);

function companyTokens(name) {
  return str(name).toLowerCase()
    .replace(/\(.*?\)/g, ' ')          // "(NASDAQ: BKNG)", "(Disney+)"
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim().split(/\s+/).filter(Boolean);
}
function companyKeyExact(name) { return companyTokens(name).join(''); }
function companyKeyLoose(name) {
  const t = companyTokens(name);
  const kept = t.filter(w => !COMPANY_NOISE.has(w));
  return (kept.length ? kept : t).join('');
}

// rows: Companies tab objects with Company, CompanyID, Aliases (';' or ',' separated)
function buildCompanyIndex(rows) {
  const exact = new Map(), loose = new Map(), names = new Map();
  const add = (map, key, id) => {
    if (!key) return;
    if (!map.has(key)) map.set(key, new Set());
    map.get(key).add(id);
  };
  for (const r of rows || []) {
    const id = str(r.CompanyID);
    if (!id) continue;
    if (!names.has(id)) names.set(id, str(r.Company));
    const variants = [str(r.Company), ...str(r.Aliases).split(/[;,|]/)].map(s => s.trim()).filter(Boolean);
    for (const v of variants) { add(exact, companyKeyExact(v), id); add(loose, companyKeyLoose(v), id); }
  }
  return { exact, loose, names };
}

function resolveCompany(index, name) {
  if (!index || !str(name)) return '';
  const pick = (set) => (set && set.size === 1 ? [...set][0] : '');
  const e = index.exact.get(companyKeyExact(name));
  if (e && e.size === 1) return pick(e);
  if (e && e.size > 1) return '';
  return pick(index.loose.get(companyKeyLoose(name)));
}

// ── enrich.js ───────────────────────────────────────────────────────────────
// Contacts hygiene + FullEnrich (v1 bulk API: submit, then poll by id).

const FULLENRICH_STATUS = { DELIVERABLE: 'VALID', HIGH_PROBABILITY: 'PROBABLE', CATCH_ALL: 'CATCH_ALL', INVALID: 'INVALID' };

function recruiterIdFor(c) {
  const key = normUrl(c.linkedinUrl) || normEmail(c.email) || `${str(c.name).toLowerCase()}|${str(c.company).toLowerCase()}`;
  return hashId('R', key);
}

function splitName(name) {
  const parts = str(name).replace(/\(.*?\)/g, ' ').split(/\s+/).filter(Boolean);
  return { first: parts[0] || '', last: parts.slice(1).join(' ') };
}

// Generated ids look like R + 9 base-36 chars. Anything else typed into the
// column (e.g. "1") is replaced, unless an Outreach row already points at it.
const RECRUITER_ID_RE = /^R[0-9a-z]{9}$/;

// A row only needs a LinkedIn URL: the id, relevance, source and date are
// filled here; name, title, company, companyId and email come from FullEnrich.
// Returns { updates: [{_row, fields}], submit: body|null, submitIds, pollIds, alerts }
function prepareEnrichment({ contacts, companyIndex, cfg, nowTs, referencedIds }) {
  const updates = [], alerts = [], pollIds = new Set(), toSubmit = [];
  const seenUrl = new Map(), seenEmail = new Map(), seenId = new Set();
  const referenced = referencedIds instanceof Set ? referencedIds : new Set(referencedIds || []);
  const batch = Math.max(1, Math.min(100, cfgNum(cfg, 'fullEnrichBatchSize', 25)));
  const defaultRelevant = cfgStr(cfg, 'defaultRelevant', 'Y').toUpperCase() === 'N' ? '' : 'Y';
  for (const c of contacts) {
    if (!str(c.name) && !str(c.linkedinUrl) && !str(c.email)) continue;
    const f = {};
    let rid = str(c.recruiterId);
    const keep = rid && !seenId.has(rid) && (RECRUITER_ID_RE.test(rid) || referenced.has(rid));
    if (!keep) { rid = recruiterIdFor(c); if (seenId.has(rid)) rid = hashId('R', `${rid}|${c._row}`); f.recruiterId = rid; }
    seenId.add(rid);
    if (!str(c.addedAt)) f.addedAt = nowTs;
    if (!str(c.source)) f.source = str(c.linkedinUrl) && !str(c.company) ? 'Manual' : 'Cowork';
    if (!str(c.isRelevant) && defaultRelevant) f.isRelevant = defaultRelevant;
